const remoteAnims = new Map();
function remoteAnim(r, dt) {
  let a = remoteAnims.get(r.id);
  if (!a) { a = { x: r.x, z: r.z, phase: 0, moving: 0 }; remoteAnims.set(r.id, a); }
  const d = Math.hypot(r.x - a.x, r.z - a.z);
  a.x = r.x; a.z = r.z;
  const speed = dt > 0 ? d / dt : 0;
  a.phase += d * 2.6;
  a.moving += ((speed > 0.6 ? 1 : 0) - a.moving) * Math.min(1, dt * 8);
  return a;
}

